import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.yo2CxoV2.js";const c=JSON.parse('{"title":"当前能力与后续方向","description":"","frontmatter":{},"headers":[],"relativePath":"reference/roadmap.md","filePath":"reference/roadmap.md","lastUpdated":1794444168000}'),s={name:"reference/roadmap.md"};function o(h,t,i,l,n,p){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="当前能力与后续方向" tabindex="-1">当前能力与后续方向 <a class="header-anchor" href="#当前能力与后续方向" aria-label="Permalink to &quot;当前能力与后续方向&quot;">​</a></h1><p>当前已发布 <strong>Ordloom 1.1.0</strong> 和四个独立子应用 <strong>0.1.0</strong>。核心提供 SDK v1、页面/数据/问卷增强和告警入队补偿；子应用最低要求核心 1.1.0。安装、升级和能力边界见 <a href="./../releases/1.1.0.html">1.1.0 发布说明</a>。</p><p><a href="https://github.com/neekin/simpleui-antd/releases/tag/ordloom-v1.1.0" target="_blank" rel="noreferrer">正式发行</a> 已完成，五个包的 GitHub/PyPI SHA256 与源码核对一致；Django 4.2/5.2/6.0 手动门禁、1801 秒双实例持续运行及 5917 次 HTTP 读取通过。公开 PyPI 默认安装选中 Django 6.1.3，补充 1491 项回归（1479 通过、12 项环境条件跳过），并验证迁移、GraphQL 和四套行业配方。以下后续业务增强继续独立排期。</p><h2 id="已实现" tabindex="-1">已实现 <a class="header-anchor" href="#已实现" aria-label="Permalink to &quot;已实现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>当前能力</th><th>指南</th></tr></thead><tbody><tr><td>页面与分析</td><td>不可变发布历史、差异、恢复草稿/回滚公开版、多序列、类型化参数联动与明细钻取</td><td><a href="./../guides/p2-page-versions.html">页面版本</a>、<a href="./../guides/p2-chart-linkage.html">联动</a></td></tr><tr><td>问卷</td><td>条件显示/跳题、精确数值/日期条件、章节和分步、历史答卷快照、后台导出与投影检索</td><td><a href="./../guides/p2-survey-steps.html">分步问卷</a>、<a href="./../guides/operations-and-submission-exports.html">答卷与运维</a></td></tr><tr><td>数据与稳定性</td><td>GraphQL/数据集/报表、公开通知故障恢复、最多 3 路读取调度、共享缓存与权限复核</td><td><a href="./../data/graphql.html">数据层</a>、<a href="./../guides/resilience-and-release-gates.html">稳定性</a></td></tr><tr><td>运维</td><td>预检、任务告警/恢复、机器人外发、持久入队补偿和只读诊断</td><td><a href="./../guides/p1-admission-and-contracts.html">入队补偿</a>、<a href="./../guides/p2-operations.html">指标</a></td></tr><tr><td>SDK 与生态</td><td>独立包菜单/专用页/静态搭建组件/任务、脚手架、应用目录、兼容工具及四套行业配方</td><td><a href="./../development/subapplications.html">SDK</a>、<a href="./../development/ecosystem.html">生态</a></td></tr><tr><td>CMS 与会员</td><td>站点/文章审核及不可变快照、可选会员内容、宿主 User 关联、注册/登录/改密/启停及业务分组</td><td><a href="./../guides/cms-and-members.html">CMS/会员</a></td></tr><tr><td>商城</td><td>商品/SKU、库存流水、会员幂等订单、人工履约、取消和超时归还库存</td><td><a href="./../guides/shop.html">商城</a></td></tr><tr><td>微信</td><td>公众号/小程序接入、回调验签/AES 收件、OAuth/code2Session、显式绑定及来源会话撤销</td><td><a href="./../guides/wechat.html">微信</a></td></tr></tbody></table><p>核心升级包含 0028/0029/0030，各子应用运行自身 0001；执行 migrate、collectstatic 并复核宿主权限和 URL 挂载。公开、注册、下单与微信等开关仍由宿主明确开启。SDK 组件当前展示静态配置/入口，不自动获得文章列表、商品数据或通用 GraphQL 绑定。</p><h2 id="p1-已完成与发行保障" tabindex="-1">P1 已完成与发行保障 <a class="header-anchor" href="#p1-已完成与发行保障" aria-label="Permalink to &quot;P1 已完成与发行保障&quot;">​</a></h2><ul><li>P1-1：外发意图与站内消息/告警状态原子保存；共享缓存租约、行锁与事件唯一、有界退避/期限、逐目标独立及入队排序。撤权或原目标变化取消旧补偿，不使用新凭据追发旧事件。</li><li>P1-2：实际 wheel/sdist ESM 语法/activate/注册与宿主 React/Ant Design 渲染；逐应用运行数与覆盖。旧包创建记录，新包同库迁移，保留业务数据、已保存组件及权限；支持 Email/UUID User 和命名空间，破坏性反例拒绝。</li><li>P1-3 已发行：核心与四子包依赖下限、文档/目录/生成器及逐包产物门禁统一；已直接安装本批原始产物，完成新 ≥30 分钟双实例持续运行，核对 PyPI 全部文件 SHA256 后公开 GitHub Release。</li></ul><p><code>ordloom_check_apps</code> 仍只检查声明，<code>--baseline</code> 不代表有数据升级；前端契约使用 jsdom。完整范围见 <a href="./../guides/p1-admission-and-contracts.html">P1 指南</a> 与源码仓库发行记录，不能替代生产负载、目标浏览器/真机或真实平台验收。</p><h2 id="下一步优先级" tabindex="-1">下一步优先级 <a class="header-anchor" href="#下一步优先级" aria-label="Permalink to &quot;下一步优先级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优先级</th><th>开发方向</th><th>范围</th></tr></thead><tbody><tr><td>P2-1</td><td>会员身份恢复与微信撤权</td><td>先验证联系方式和真实平台事件，再实现找回/注销/个人数据流程及来源会话撤销；历史未验证邮箱不直接用于授权</td></tr><tr><td>P2-2</td><td>CMS 历史恢复与业务数据组件</td><td>先补全文比较/恢复草稿，再提供受控文章列表、商品卡片；公开查询复核发布快照、会员与当前权限</td></tr><tr><td>P2-3</td><td>Payments 与商城支付闭环</td><td>单商户/CNY/一个实际渠道，核价、回调验签幂等、主动查询、退款对账和库存补偿；支付包尚未实现</td></tr><tr><td>P2-4</td><td>微信业务消息</td><td>从一个已提交业务事件开始，定义消费、重放/重试、订阅授权、留存和平台验收，再扩展菜单/素材</td></tr><tr><td>P3</td><td>行业应用与生态分发</td><td>CRM、预约、审批、工单、营销逐项 MVP；出现真实第三方需求后维护来源/签名和更广兼容矩阵</td></tr></tbody></table><p>高级数据按具体模型与规模推进：受控公式/同比环比、多值关联或多模型、第三方 HTTP 输入、数据库与全文索引适配。每项先定义权限、类型、精度、查询预算与部署验收，不开放任意 ORM 路径或在线代码。</p><p>共享缓存、ASGI 代理、任务调度、组织/租户映射、真实机器人/微信账号、HTTPS、目标大屏长期轮播及真机由宿主验证。云函数与在线自定义代码继续仅调研，尚未开发。</p>',13)])])}const u=e(s,[["render",o]]);export{c as __pageData,u as default};
